package org.animallink.adoption.api; import jakarta.validation.constraints.*; import java.time.*; import java.util.*; import org.animallink.adoption.application.AdoptionHandoverService;
public final class AdoptionHandoverDtos{private AdoptionHandoverDtos(){} public record InitiateRequest(@NotNull OffsetDateTime scheduledAt,@Size(max=500) String note){} public record CancelRequest(@NotBlank @Size(max=500) String reason){} public record GovernanceResponse(String handoverId,String selectionId,String listingId,String applicationId,String selectedApplicantUserId,String status,Instant scheduledAt,String initiatedByUserId,Instant initiatedAt,String completedByUserId,Instant completedAt,String cancelledByUserId,Instant cancelledAt,String cancelReason,String note){public static GovernanceResponse from(AdoptionHandoverService.View v){var h=v.handover();return new GovernanceResponse(h.id(),h.selectionId(),v.listingId(),v.applicationId(),v.applicantUserId(),h.status().name(),h.scheduledAt(),h.initiatedByUserId(),h.initiatedAt(),h.completedByUserId(),h.completedAt(),h.cancelledByUserId(),h.cancelledAt(),h.cancelReason(),h.note());}} public record ApplicantResponse(String handoverId,String listingId,String applicationId,String status,Instant scheduledAt,Instant initiatedAt,Instant completedAt){public static ApplicantResponse from(AdoptionHandoverService.ApplicantView v){return new ApplicantResponse(v.handoverId(),v.listingId(),v.applicationId(),v.status(),v.scheduledAt(),v.initiatedAt(),v.completedAt());}}
}
